# owner: platform
"""Snap span times to a fixed step and label them for payroll."""

from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span

MINUTES_PER_HOUR = 60

# ---
def round_labels(spans: Iterable[Span], step_minutes: int) -> List[str]:
    """Snap spans to the nearest step and label them, like 09:00-17:15 (8h 15m)."""
    _check_step(step_minutes)
    return [_label(_round_span(span, step_minutes)) for span in spans]

def _check_step(step_minutes: int) -> None:
    if step_minutes <= 0 or MINUTES_PER_HOUR % step_minutes:
        raise ValueError(f"step must divide an hour evenly, got {step_minutes}")

def _round_minute(minute: int, step_minutes: int) -> int:
    """Nearest multiple of the step. Exact halves go up."""
    return (2 * minute + step_minutes) // (2 * step_minutes) * step_minutes

def _round_span(span: Span, step_minutes: int) -> Span:
    rounded_start = _round_minute(span.start, step_minutes)
    rounded_end = _round_minute(span.end, step_minutes)
    if rounded_start >= rounded_end:
        raise ValueError(f"{format_span(span)} is empty after rounding")
    return Span(rounded_start, rounded_end)

def _label(span: Span) -> str:
    hours, minutes = divmod(span.minutes, MINUTES_PER_HOUR)
    return f"{format_span(span)} ({hours}h {minutes}m)"
